from abc import ABC, abstractmethod
import numpy as np


class Objective(ABC):
    """Base class for all objective functions."""

    @property
    @abstractmethod
    def name(self) -> str:
        ...

    @property
    def is_classification(self) -> bool:
        return False

    @abstractmethod
    def loss(self, y_true: np.ndarray, y_pred: np.ndarray) -> float:
        """Compute scalar loss value."""
        ...

    @abstractmethod
    def gradients(self, y_true: np.ndarray, y_pred: np.ndarray) -> np.ndarray:
        """Compute first-order gradients (negative direction)."""
        ...

    @abstractmethod
    def hessians(self, y_true: np.ndarray, y_pred: np.ndarray) -> np.ndarray:
        """Compute second-order gradients (hessians)."""
        ...

    def init_score(self, y: np.ndarray) -> float:
        """Initial prediction score (e.g. log-odds for binary, mean for regression)."""
        return 0.0

import numpy as np
from .base import Objective


class MeanSquaredError(Objective):
    name = "mse"

    def loss(self, y_true, y_pred):
        return float(np.mean((y_true - y_pred) ** 2))

    def gradients(self, y_true, y_pred):
        return -(y_true - y_pred)

    def hessians(self, y_true, y_pred):
        return np.ones_like(y_true)

    def init_score(self, y):
        return float(np.mean(y))


class MeanAbsoluteError(Objective):
    name = "mae"

    def loss(self, y_true, y_pred):
        return float(np.mean(np.abs(y_true - y_pred)))

    def gradients(self, y_true, y_pred):
        diff = y_pred - y_true
        return -np.sign(diff)

    def hessians(self, y_true, y_pred):
        return np.ones_like(y_true)

    def init_score(self, y):
        return float(np.median(y))


class HuberLoss(Objective):
    name = "huber"

    def __init__(self, alpha: float = 0.9):
        self.alpha = alpha

    def loss(self, y_true, y_pred):
        residual = y_true - y_pred
        delta = self._delta(y_true)
        abs_r = np.abs(residual)
        quadratic = np.minimum(abs_r, delta)
        linear = abs_r - quadratic
        return float(np.mean(0.5 * quadratic ** 2 + delta * linear))

    def gradients(self, y_true, y_pred):
        residual = y_true - y_pred
        delta = self._delta(y_true)
        abs_r = np.abs(residual)
        grad = np.where(abs_r <= delta, -residual, -delta * np.sign(residual))
        return grad

    def hessians(self, y_true, y_pred):
        residual = y_true - y_pred
        delta = self._delta(y_true)
        return np.where(np.abs(residual) <= delta, 1.0, 0.0)

    def init_score(self, y):
        return float(np.median(y))

    def _delta(self, y_true):
        residual = y_true - np.median(y_true)
        return np.percentile(np.abs(residual), self.alpha * 100)


class PoissonLoss(Objective):
    name = "poisson"

    def loss(self, y_true, y_pred):
        y_pred = np.clip(y_pred, 1e-10, None)
        return float(np.mean(y_pred - y_true * np.log(y_pred)))

    def gradients(self, y_true, y_pred):
        y_pred = np.clip(y_pred, 1e-10, None)
        return -(y_true / y_pred - 1.0)

    def hessians(self, y_true, y_pred):
        y_pred = np.clip(y_pred, 1e-10, None)
        return y_true / (y_pred ** 2)

    def init_score(self, y):
        return float(np.log(np.mean(y)))


class QuantileLoss(Objective):
    name = "quantile"

    def __init__(self, quantile: float = 0.5):
        self.quantile = quantile

    def loss(self, y_true, y_pred):
        residual = y_true - y_pred
        return float(np.mean(np.where(residual >= 0, self.quantile * residual,
                                       (self.quantile - 1) * residual)))

    def gradients(self, y_true, y_pred):
        residual = y_true - y_pred
        return -np.where(residual >= 0, self.quantile, self.quantile - 1)

    def hessians(self, y_true, y_pred):
        return np.ones_like(y_true)

    def init_score(self, y):
        return float(np.percentile(y, self.quantile * 100))

import numpy as np
from .base import Objective


def _sigmoid(x):
    x = np.clip(x, -500, 500)
    return 1.0 / (1.0 + np.exp(-x))


class BinaryLogloss(Objective):
    name = "binary"

    @property
    def is_classification(self):
        return True

    def loss(self, y_true, y_pred):
        p = _sigmoid(y_pred)
        p = np.clip(p, 1e-10, 1 - 1e-10)
        return float(-np.mean(y_true * np.log(p) + (1 - y_true) * np.log(1 - p)))

    def gradients(self, y_true, y_pred):
        p = _sigmoid(y_pred)
        return -(y_true - p)

    def hessians(self, y_true, y_pred):
        p = _sigmoid(y_pred)
        return p * (1 - p)

    def init_score(self, y):
        p = np.mean(y)
        p = np.clip(p, 1e-10, 1 - 1e-10)
        return float(np.log(p / (1 - p)))


class MulticlassLogloss(Objective):
    name = "multiclass"

    def __init__(self, num_classes: int = None):
        self.num_classes = num_classes

    @property
    def is_classification(self):
        return True

    def loss(self, y_true, y_pred):
        probs = self._softmax(y_pred)
        num_classes = probs.shape[1]
        y_int = y_true.astype(int)
        log_probs = np.log(np.clip(probs, 1e-10, 1.0))
        return float(-np.mean(log_probs[np.arange(len(y_int)), y_int]))

    def gradients(self, y_true, y_pred):
        probs = self._softmax(y_pred)
        num_classes = probs.shape[1]
        y_onehot = np.zeros_like(probs)
        y_int = y_true.astype(int)
        y_onehot[np.arange(len(y_int)), y_int] = 1.0
        return -(y_onehot - probs)

    def hessians(self, y_true, y_pred):
        probs = self._softmax(y_pred)
        return probs * (1 - probs)

    def init_score(self, y):
        if self.num_classes is None:
            self.num_classes = int(y.max()) + 1
        counts = np.bincount(y.astype(int), minlength=self.num_classes)
        probs = counts / len(y)
        probs = np.clip(probs, 1e-10, 1.0)
        probs /= probs.sum()
        log_probs = np.log(probs)
        return log_probs - log_probs.mean()

    def _softmax(self, x):
        x_shifted = x - x.max(axis=1, keepdims=True)
        exp_x = np.exp(x_shifted)
        return exp_x / exp_x.sum(axis=1, keepdims=True)

