import numpy as np
from typing import Optional


def rmse(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.sqrt(np.mean((y_true - y_pred) ** 2)))


def mae(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean(np.abs(y_true - y_pred)))


def mse(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean((y_true - y_pred) ** 2))


def logloss(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    p = 1.0 / (1.0 + np.exp(-np.clip(y_pred, -500, 500)))
    p = np.clip(p, 1e-10, 1 - 1e-10)
    return float(-np.mean(y_true * np.log(p) + (1 - y_true) * np.log(1 - p)))


def accuracy(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean((y_true > 0.5).astype(int) == y_pred.astype(int)))


def auc(y_true: np.ndarray, y_score: np.ndarray) -> float:
    desc_idx = np.argsort(-y_score)
    y_true_sorted = y_true[desc_idx]
    n_pos = np.sum(y_true_sorted == 1)
    n_neg = np.sum(y_true_sorted == 0)
    if n_pos == 0 or n_neg == 0:
        return 0.5
    tpr_cumsum = np.cumsum(y_true_sorted == 1) / n_pos
    fpr_cumsum = np.cumsum(y_true_sorted == 0) / n_neg
    tpr_cumsum = np.concatenate(([0.0], tpr_cumsum))
    fpr_cumsum = np.concatenate(([0.0], fpr_cumsum))
    return float(np.trapz(tpr_cumsum, fpr_cumsum))


def precision(y_true: np.ndarray, y_pred: np.ndarray, threshold: float = 0.5) -> float:
    pred_pos = (y_pred >= threshold).astype(int)
    tp = np.sum((pred_pos == 1) & (y_true.astype(int) == 1))
    fp = np.sum((pred_pos == 1) & (y_true.astype(int) == 0))
    if tp + fp == 0:
        return 0.0
    return float(tp / (tp + fp))


def recall(y_true: np.ndarray, y_pred: np.ndarray, threshold: float = 0.5) -> float:
    pred_pos = (y_pred >= threshold).astype(int)
    tp = np.sum((pred_pos == 1) & (y_true.astype(int) == 1))
    fn = np.sum((pred_pos == 0) & (y_true.astype(int) == 1))
    if tp + fn == 0:
        return 0.0
    return float(tp / (tp + fn))


def f1_score(y_true: np.ndarray, y_pred: np.ndarray, threshold: float = 0.5) -> float:
    p = precision(y_true, y_pred, threshold)
    r = recall(y_true, y_pred, threshold)
    if p + r == 0:
        return 0.0
    return 2 * p * r / (p + r)


def multiclass_accuracy(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean(np.argmax(y_pred, axis=1) == y_true.astype(int)))

from .metrics import (
    rmse, mae, mse, logloss, accuracy, auc,
    precision, recall, f1_score, multiclass_accuracy,
)

REGRESSION_METRICS = {"rmse": rmse, "mae": mae, "mse": mse}
BINARY_METRICS = {"logloss": logloss, "accuracy": accuracy, "auc": auc,
                  "precision": precision, "recall": recall, "f1": f1_score}
MULTICLASS_METRICS = {"accuracy": multiclass_accuracy}

__all__ = [
    "rmse", "mae", "mse", "logloss", "accuracy", "auc",
    "precision", "recall", "f1_score", "multiclass_accuracy",
    "REGRESSION_METRICS", "BINARY_METRICS", "MULTICLASS_METRICS",
]

import time
from typing import Optional, List, Dict, Callable


class CallbackEnv:
    def __init__(self):
        self.iteration: int = 0
        self.train_loss: float = 0.0
        self.valid_losses: Dict[str, float] = {}
        self.best_iteration: int = 0
        self.best_score: float = float("inf")
        self.model = None


class Callback:
    def __init__(self):
        pass

    def __call__(self, env: CallbackEnv):
        pass

    def init(self, env: CallbackEnv):
        pass


class EarlyStopping(Callback):
    def __init__(self, stopping_rounds: int = 50, metric_name: str = "valid_0", verbose: bool = True):
        super().__init__()
        self.stopping_rounds = stopping_rounds
        self.metric_name = metric_name
        self.verbose = verbose
        self.best_score = float("inf")
        self.best_iter = 0

    def init(self, env: CallbackEnv):
        self.best_score = float("inf")
        self.best_iter = 0

    def __call__(self, env: CallbackEnv):
        score = env.valid_losses.get(self.metric_name, env.train_loss)
        if score < self.best_score:
            self.best_score = score
            self.best_iter = env.iteration
            env.best_iteration = env.iteration
            env.best_score = score
        elif env.iteration - self.best_iter >= self.stopping_rounds:
            if self.verbose:
                print(f"Early stopping at round {env.iteration}, best iteration: {self.best_iter}, best score: {self.best_score:.6f}")
            return True
        return False


class LogCallback(Callback):
    def __init__(self, period: int = 1):
        super().__init__()
        self.period = period

    def __call__(self, env: CallbackEnv):
        if env.iteration % self.period == 0:
            msg = f"[{env.iteration:5d}] train loss: {env.train_loss:.6f}"
            for k, v in env.valid_losses.items():
                msg += f" | {k}: {v:.6f}"
            print(msg)


class LearningRateScheduler(Callback):
    def __init__(self, decay_factor: float = 0.99, min_lr: float = 1e-5):
        super().__init__()
        self.decay_factor = decay_factor
        self.min_lr = min_lr

    def __call__(self, env: CallbackEnv):
        if env.model is not None and hasattr(env.model, 'learning_rate'):
            env.model.learning_rate = max(
                env.model.learning_rate * self.decay_factor,
                self.min_lr,
            )

